import { useState, useRef, useId } from 'react';
import type { KeyboardEvent, ChangeEvent } from 'react';
import { Button, Input } from '@jinx-ui/react';

export type TagPickerProps = {
  label?: string;
  placeholder?: string;
  value?: string[];
  defaultValue?: string[];
  maxTags?: number;
  onChange?: (tags: string[]) => void;
};

export default function TagPicker({
  label = 'Теги статьи',
  placeholder = 'Введите тег и нажмите Enter',
  value,
  defaultValue = [],
  maxTags = 12,
  onChange,
}: TagPickerProps) {
  const [internalTags, setInternalTags] = useState<string[]>(defaultValue);
  const [draft, setDraft] = useState('');
  const inputRef = useRef<HTMLInputElement>(null);
  const inputId = useId();
  const hintId = `${inputId}-hint`;

  const tags = value ?? internalTags;
  const isFull = tags.length >= maxTags;

  const commit = (next: string[]) => {
    if (value === undefined) setInternalTags(next);
    onChange?.(next);
  };

  const addTag = (raw: string) => {
    const tag = raw.trim().replace(/\s+/g, ' ');
    if (!tag || isFull) return;
    if (tags.some((existing) => existing.toLowerCase() === tag.toLowerCase())) {
      setDraft('');
      return;
    }
    commit([...tags, tag]);
    setDraft('');
  };

  const removeTag = (tag: string) => {
    commit(tags.filter((existing) => existing !== tag));
    inputRef.current?.focus();
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Enter' || event.key === ',') {
      event.preventDefault();
      addTag(draft);
      return;
    }
    if (event.key === 'Backspace' && draft === '' && tags.length > 0) {
      event.preventDefault();
      removeTag(tags[tags.length - 1]);
    }
  };

  const handleChange = (event: ChangeEvent<HTMLInputElement>) => {
    const raw = event.target.value;
    if (raw.includes(',')) {
      const parts = raw.split(',');
      const tail = parts.pop() ?? '';
      parts.forEach(addTag);
      setDraft(tail);
      return;
    }
    setDraft(raw);
  };

  return (
    <div
      className="jx-field jx-stack"
      style={{ display: 'grid', gap: 'var(--jx-space-2)' }}
    >
      <label className="jx-label" htmlFor={inputId}>
        {label}
      </label>

      <Input
        id={inputId}
        ref={inputRef}
        className="jx-input"
        value={draft}
        placeholder={isFull ? 'Достигнут лимит тегов' : placeholder}
        disabled={isFull}
        aria-describedby={hintId}
        onChange={handleChange}
        onKeyDown={handleKeyDown}
        onBlur={() => addTag(draft)}
      />

      <p id={hintId} className="jx-text-muted jx-caption">
        {`Enter или запятая добавляют тег · ${tags.length} из ${maxTags}`}
      </p>

      {tags.length > 0 && (
        <ul
          className="jx-cluster"
          aria-label="Выбранные теги"
          style={{
            display: 'flex',
            flexWrap: 'wrap',
            gap: 'var(--jx-space-2)',
            margin: 0,
            padding: 0,
            listStyle: 'none',
          }}
        >
          {tags.map((tag) => (
            <li
              key={tag}
              className="jx-tag"
              style={{
                display: 'inline-flex',
                alignItems: 'center',
                gap: 'var(--jx-space-1)',
                borderRadius: 'var(--jx-radius)',
                paddingInline: 'var(--jx-space-2)',
                background: 'var(--jx-surface-2)',
                color: 'var(--jx-text)',
                border: 'var(--jx-border-width) solid var(--jx-border)',
              }}
            >
              <span className="jx-tag-label">{tag}</span>
              <Button
                type="button"
                variant="ghost"
                size="sm"
                className="jx-tag-remove"
                aria-label={`Удалить тег ${tag}`}
                onClick={() => removeTag(tag)}
              >
                ×
              </Button>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

